using Microsoft.Azure.WebJobs;
using Microsoft.Extensions.Logging;

public static class ProcessOrderFunction
{
    [FunctionName("ProcessOrderFunction")]
    public static void Run(
        [ServiceBusTrigger("orders", Connection = "ServiceBusConnection")] string orderJson,
        ILogger log)
    {
        log.LogInformation($"Processing order: {orderJson}");
        // Your business logic here
    }
}

[FunctionName("NotifyOnNewOrder")]
public static void Run(
    [ServiceBusTrigger("orders", "notifications", Connection = "ServiceBusConnection")] string message,
    ILogger log)
{
    log.LogInformation($"New order event: {message}");
    // Send email, SMS, or other notifications
}
